-- Идемпотентные демонстрационные данные. Существующие магазины и товары чернового проекта сохраняются.
INSERT INTO categories(name,slug,description) VALUES
 ('Строительные материалы','building-materials','Материалы для строительства и ремонта.'),('Отделочные материалы','finishing','Материалы для внутренней отделки.'),('Инструменты и оборудование','tools','Ручной и электроинструмент.'),('Сантехника','plumbing','Сантехника и водоснабжение.'),('Электрика и освещение','electrical','Электротовары и освещение.'),('Двери и окна','doors-windows','Двери, окна и комплектующие.'),('Кровля и фасад','roofing','Кровельные и фасадные материалы.'),('Товары для дома и участка','home-garden','Товары для дома и участка.'),('Другое','other','Другие строительные товары.') ON CONFLICT(slug) DO NOTHING;
INSERT INTO stores(slug,name,description,address,phone) VALUES('aqua','АкваДом','Сантехника и оборудование для ванной комнаты.','г. Калуга','+7 (4842) 00-00-01'),('master','МастерКрепёж','Крепёж, инструмент и расходные материалы.','г. Калуга','+7 (4842) 00-00-02'),('svet','Свет и Дом','Электрика и товары для дома.','г. Калуга','+7 (4842) 00-00-03') ON CONFLICT(slug) DO NOTHING;
INSERT INTO products(store_id,category_id,unit_id,sku,name,description,price,stock,image_url,coverage_per_package,waste_factor,weight_kg)
SELECT s.id,c.id,u.id,v.sku,v.name,v.description,v.price,v.stock,v.image_url,v.coverage,v.waste,v.weight FROM (VALUES
 ('aqua','plumbing','AQUA-001','Смеситель для раковины','Однорычажный смеситель для ванной комнаты.',2490,18,NULL::text,NULL::numeric,1.0,1.4,'шт.'),('aqua','plumbing','AQUA-002','Раковина керамическая','Керамическая раковина белого цвета.',3890,12,NULL,NULL,1.0,11.0,'шт.'),('aqua','plumbing','AQUA-003','Труба ПВХ 50 мм','Канализационная труба, цена указана за метр.',220,100,NULL,NULL,1.0,0.4,'м'),('master','tools','MSTR-001','Саморезы универсальные','Упаковка 100 штук.',290,45,NULL,NULL,1.0,0.3,'уп.'),('master','building-materials','MSTR-002','Цемент М500 25 кг','Портландцемент для строительных работ.',560,80,NULL,1.0,1.05,25.0,'меш.'),('master','finishing','MSTR-003','Краска интерьерная 9 л','Водно-дисперсионная краска, покрытие 75 м² на упаковку.',1790,24,NULL,75,1.1,11.0,'шт.'),('svet','electrical','SVET-001','Кабель ВВГнг 3×2,5','Медный силовой кабель, цена указана за метр.',118,250,NULL,NULL,1.0,0.15,'м'),('svet','electrical','SVET-002','Розетка настенная','Розетка с заземлением, белая.',320,60,NULL,NULL,1.0,0.2,'шт.'),('svet','home-garden','SVET-003','Светильник потолочный','Светодиодный светильник для дома.',1450,16,NULL,NULL,1.0,1.2,'шт.')
) AS v(store_slug,category_slug,sku,name,description,price,stock,image_url,coverage,waste,weight,unit_short)
JOIN stores s ON s.slug=v.store_slug JOIN categories c ON c.slug=v.category_slug JOIN units u ON u.short_name=v.unit_short
WHERE NOT EXISTS(SELECT 1 FROM products) ON CONFLICT(store_id,sku) DO NOTHING;